import os, re

def load_grids() -> dict:
    """Load all grids from session logs including kept pairs."""
    session_dir = os.environ.get('RLM_SESSION_DIR')
    if not session_dir:
        return {}

    # Get this instance's log file
    log_path = os.path.join(session_dir, '../../sessions', os.path.basename(session_dir) + '.jsonl')
    log_path = os.path.normpath(log_path)

    G = {}
    try:
        with open(log_path, 'r') as f:
            content = f.read()

        # Find all demo pairs and test input
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
        for match in re.finditer(pattern, content):
            key = match.group(1)
            name, h, w = match.group(2), int(match.group(3)), int(match.group(4))

            rows = []
            rest = content[match.end():].split('\n')[:h]
            for row_str in rest:
                if row_str.strip():
                    rows.append([int(x) for x in row_str.split()])

            if key not in G and len(rows) == h and all(len(r) == w for r in rows):
                G[key] = rows

        return G
    except Exception as e:
        print(f"Error loading grids: {e}")
        return {}

G = load_grids()
print("Available grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")

